solution:
alter table produits enable row level security;
create policy catalogue_public on produits for select to anon, authenticated using (true);
alter table commandes enable row level security;
create policy mes_commandes on commandes for select to authenticated using (client_id = auth.uid());
create function annuler_commande(p_id bigint) returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  c commandes;
begin
  select * into c from commandes where id = p_id and client_id = auth.uid() and statut = 'en_attente';
  if not found then
    raise exception 'commande introuvable';
  end if;
  update produits set stock = stock + c.quantite where id = c.produit_id;
  delete from commandes where id = p_id;
end;
$$;
